CREATE VIEW v20712 AS SELECT x7.v20440, x7.v20440, MIN(x7.v20440 + x7.v20439) OVER (ORDER BY AVG(x7.v20439) RANGE BETWEEN INTERVAL (NULL) HOUR PRECEDING AND CURRENT ROW) AS x4, SUM(x7.v20438 + x7.v20440) OVER (ORDER BY x7.v20438 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS x5 FROM v20436 AS x7